import json,subprocess,urllib.request,hashlib
try:
 url="https://raw.githubusercontent.com/martaxi-boss/Vivoapk/169a85a47796df16ebd3aa43356563a7a7963f4d/infra/deploy_jellyfin_auth.py"
 with urllib.request.urlopen(url,timeout=18) as f:code=f.read(30000)
 actual=hashlib.sha1(b"blob "+str(len(code)).encode()+bytes([0])+code).hexdigest()
 if actual!="1f26bf1249a5d4e53fdb7840526685a2981053e3":raise RuntimeError("source_git_blob_mismatch")
 p=subprocess.run(["sudo","-n","python3","-","preflight","--sha","169a85a47796df16ebd3aa43356563a7a7963f4d"],input=code,capture_output=True,timeout=100)
 try:d=json.loads(p.stdout)
 except:d={"status":"invalid_script_report"}
 allowed=("operation","mode","status","reason","source_sha","changes","plugin_preexisting","admin_record_present")
 out={k:d[k] for k in allowed if k in d}
 out["exit"]=p.returncode;out["verified_git_blob"]=True
 print(json.dumps(out,sort_keys=True))
except Exception as e:print(json.dumps({"status":"blocked","error_type":type(e).__name__}))
